cypress_script:
describe('Buttons Functionality', () => {
  it('should successfully click the Click Me button', () => {
    cy.visit('https://demoqa.com/buttons');
    cy.get('button#sp5Bi').click();
    cy.url().should('eq', 'https://demoqa.com/buttons');
  });
  it('should handle double-click on the Double Click Me button', () => {
    cy.visit('https://demoqa.com/buttons');
    cy.get('button#doubleClickBtn').dblclick();
    cy.url().should('eq', 'https://demoqa.com/buttons');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

 test.describe('Buttons Functionality', () => {
   test('should successfully click the Click Me button', async ({ page }) => {
     await page.goto('https://demoqa.com/buttons');
     await page.click('button#sp5Bi');
     expect(page.url()).toBe('https://demoqa.com/buttons');
   });
   test('should handle double-click on the Double Click Me button', async ({ page }) => {
     await page.goto('https://demoqa.com/buttons');
     await page.dblclick('button#doubleClickBtn');
     expect(page.url()).toBe('https://demoqa.com/buttons');
   });
});
